use crate::*;
use crate::owned::NativeRecordStorage;
#[test]fn actual_native_record_typed_backing_keeps_null_uninitialized_and_taken_ownership(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let mut owner=NativeRecordStorage::<u64>::empty(1);let g=RetainedCloneGrant{maximum_items:1,..bank};assert_eq!(owner.reserve(RetainedCloneGrant{maximum_items:0,..g}).work,0);let((turn,attempts),heap)=crate::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||owner.reserve(g)));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);fuel-=turn.work;assert!(turn.result.is_err());assert!(!owner.reserved());for phase in 0..2{let g=RetainedCloneGrant{maximum_items:1,..bank};let(turn,heap)=crate::observe_retirement_allocations(||if phase==0{owner.reserve(g)}else{owner.initialize(g)});let p=turn.result.unwrap().progress();assert_eq!(turn.work,1);assert!(p.fits(bank));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;fuel-=turn.work;}let mut value=Some(law["value"].as_u64().unwrap());let denied=unsafe{owner.place_field(0,&mut value,RetainedCloneGrant{maximum_items:0,..bank})};assert_eq!(denied.work,0);assert!(value.is_some());let(turn,heap)=crate::observe_retirement_allocations(||unsafe{owner.place_field(0,&mut value,RetainedCloneGrant{maximum_items:1,..bank})});let p=turn.result.unwrap().unwrap();assert_eq!(heap,(0,0));assert_eq!(turn.work,1);assert_eq!(p.copied_bytes,std::mem::size_of::<u64>());assert!(value.is_none());bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;fuel-=turn.work;let(turn,heap)=crate::observe_retirement_allocations(||unsafe{owner.take_initialized(RetainedCloneGrant{maximum_items:0,..bank})});assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(heap,(0,0));let(turn,heap)=crate::observe_retirement_allocations(||unsafe{owner.take_initialized(RetainedCloneGrant{maximum_items:1,..bank})});let(output,p)=turn.result.unwrap().unwrap();assert_eq!(turn.work,1);assert_eq!(heap,(0,0));assert_eq!(serde_json::to_value(output).unwrap(),law["value"]);assert_eq!(p.copied_bytes,0);bank.maximum_items-=p.copied_items;fuel-=turn.work;assert_eq!(unsafe{owner.take_initialized(Default::default())}.work,0);let(turn,heap)=crate::observe_retirement_allocations(||owner.release(RetainedCloneGrant{maximum_items:1,..bank}));let p=turn.result.unwrap().progress();assert_eq!(turn.work,1);assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(p.fits(bank));fuel-=turn.work;assert!(owner.terminal_is_empty());assert!(fuel<s["fuel"].as_u64().unwrap());}
